// Negative control (mutate.mjs is unavailable in this install: it needs polynv/).
// Writes mutants of reference.cjs into spec/mutants/, then replays each against
// the corpus and model-checks it; every mutant must be caught by one or both.
// Usage: node spec/negative-control.mjs
import { execFileSync } from 'node:child_process';
import { mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const P = join(HERE, '..', 'tools', 'polygraph', 'scripts');
const ref = readFileSync(join(HERE, 'reference.cjs'), 'utf-8');

const MUTANTS = {
  'cancel-while-placed': ["if (model.status === 'placed') return reject('payment in progress');",
    "if (model.status === 'placed') { next.status = 'cancelled'; unchanged('items', 'charges', 'refunds', 'pending'); return; }"],
  'cap-4': ['const MAX_ITEMS = 3;', 'const MAX_ITEMS = 4;'],
  'place-empty': ["if (model.items <= 0) return reject('draft is empty');\n        next.status = 'placed';", "next.status = 'placed';"],
  'ship-from-placed': ["if (model.status !== 'paid') return reject('order is not paid');", "if (model.status !== 'paid' && model.status !== 'placed') return reject('order is not paid');"],
  'no-refund': ['next.refunds = model.refunds + 1;', "unchanged('refunds');"],
};

const dir = join(HERE, 'mutants');
rmSync(dir, { recursive: true, force: true });
let survivors = 0;
for (const [name, [from, to]] of Object.entries(MUTANTS)) {
  if (!ref.includes(from)) throw new Error(`mutant ${name}: pattern not found`);
  const d = join(dir, name);
  mkdirSync(d, { recursive: true });
  const file = join(d, `${name}.cjs`);
  writeFileSync(file, ref.replace(from, to));
  const run = (args) => { try { return { ok: true, out: execFileSync('node', args, { encoding: 'utf-8', stdio: 'pipe' }) }; } catch (e) { return { ok: false, out: `${e.stdout}${e.stderr}` }; } };
  const replay = run([join(P, 'verify.mjs'), '--contract', join(HERE, 'contract.json'), '--traces', join(HERE, 'traces'), '--specs', d, '--out', join(d, 'out'), '--no-auto-regen']);
  const replayCaught = !/(\d+)\/\1 windows consistent/.test(replay.out);
  const check = run([join(P, 'check.mjs'), '--spec', file, '--contract', join(HERE, 'contract.json'), '--invariants', join(HERE, 'invariants.mjs')]);
  const checkCaught = !check.ok || !/no invariant violations reachable/.test(check.out);
  const caught = replayCaught || checkCaught;
  if (!caught) survivors++;
  console.log(`${caught ? 'KILLED  ' : 'SURVIVED'} ${name}: replay ${replayCaught ? 'caught' : 'clean'}, check ${checkCaught ? 'caught' : 'clean'}`);
}
rmSync(dir, { recursive: true, force: true });
process.exit(survivors ? 1 : 0);

