test('first charge failed -> declined; retry failed -> failed', async () => {
  const h = await createHost();
  refused(await h.retryPayment('o'));
  const e = await placed(h);
  refused(await h.retryPayment('o'));
  await h.completeEffect(e.id, 'failed');
  assert.deepEqual(await h.order('o'), { status: 'declined', items: 2, charges: 1, refunds: 0 });
  assert.deepEqual(await h.pendingEffects(), []);
  for (const c of ['create', 'addItem', 'removeItem', 'place', 'ship', 'cancel']) refused(await h[c]('o'));
  assert.deepEqual(await h.retryPayment('o'), ok);
  refused(await h.retryPayment('o'));
  assert.deepEqual(await h.order('o'), { status: 'placed', items: 2, charges: 2, refunds: 0 });
  const [e2] = await h.pendingEffects();
  assert.notEqual(e2.id, e.id);
  assert.deepEqual({ from: e2.from, kind: e2.kind, data: e2.data }, { from: 'o', kind: 'payment.charge', data: { amount: 2 } });
  await h.completeEffect(e2.id, 'failed');
  assert.deepEqual(await h.order('o'), { status: 'failed', items: 2, charges: 2, refunds: 0 });
  assert.deepEqual(await h.pendingEffects(), []);
  for (const c of ['addItem', 'removeItem', 'place', 'ship', 'cancel', 'retryPayment']) refused(await h[c]('o'));
});

test('retry succeeds -> paid, ship; or cancel with refund', async () => {
  const h = await createHost();
  for (const id of ['s', 'c']) {
    await h.completeEffect((await placed(h, id, 1)).id, 'failed');
    await h.retryPayment(id);
    await h.completeEffect((await h.pendingEffects()).find((x) => x.from === id).id, 'ok');
    assert.equal((await h.order(id)).status, 'paid');
  }
  assert.deepEqual(await h.ship('s'), ok);
  assert.deepEqual(await h.order('s'), { status: 'shipped', items: 1, charges: 2, refunds: 0 });
  assert.deepEqual(await h.cancel('c'), ok);
  assert.deepEqual(await h.order('c'), { status: 'cancelled', items: 1, charges: 2, refunds: 1 });
});

