import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

const ok = { ok: true };
const refused = (r) => assert.equal(r.ok, false) || assert.equal(typeof r.reason, 'string');

async function placed(h, id = 'o', n = 2) {
  await h.create(id);
  for (let i = 0; i < n; i++) await h.addItem(id);
  assert.deepEqual(await h.place(id), ok);
  return (await h.pendingEffects()).find((e) => e.from === id);
}

test('fresh system', async () => {
  const h = await createHost();
  assert.equal(await h.order('x'), null);
  assert.deepEqual(await h.pendingEffects(), []);
  for (const c of ['addItem', 'removeItem', 'place', 'ship', 'cancel']) refused(await h[c]('x'));
  assert.equal(await h.order('x'), null);
});

test('create and items', async () => {
  const h = await createHost();
  assert.deepEqual(await h.create('a'), ok);
  refused(await h.create('a'));
  assert.deepEqual(await h.order('a'), { status: 'draft', items: 0, charges: 0, refunds: 0 });
  refused(await h.removeItem('a'));
  refused(await h.place('a'));
  for (let i = 0; i < 3; i++) assert.deepEqual(await h.addItem('a'), ok);
  refused(await h.addItem('a'));
  assert.equal((await h.order('a')).items, 3);
  assert.deepEqual(await h.removeItem('a'), ok);
  assert.equal((await h.order('a')).items, 2);
});

test('place charges once, ok -> paid -> shipped', async () => {
  const h = await createHost();
  const e = await placed(h, 'o', 2);
  assert.deepEqual({ ...e, id: undefined }, { id: undefined, from: 'o', kind: 'payment.charge', data: { amount: 2 } });
  assert.deepEqual(await h.order('o'), { status: 'placed', items: 2, charges: 1, refunds: 0 });
  refused(await h.place('o'));
  refused(await h.addItem('o'));
  refused(await h.cancel('o'));
  refused(await h.ship('o'));
  await h.completeEffect(e.id, 'ok');
  assert.deepEqual(await h.pendingEffects(), []);
  assert.equal((await h.order('o')).status, 'paid');
  assert.deepEqual(await h.ship('o'), ok);
  assert.equal((await h.order('o')).status, 'shipped');
  for (const c of ['addItem', 'removeItem', 'place', 'ship', 'cancel']) refused(await h[c]('o'));
  await h.completeEffect(e.id, 'failed');
  assert.deepEqual(await h.order('o'), { status: 'shipped', items: 2, charges: 1, refunds: 0 });
});

test('first charge failed -> declined; retry failed -> failed', async () => {
  const h = await createHost();
  refused(await h.retryPayment('o'));
  const e = await placed(h);
  refused(await h.retryPayment('o'));
  await h.completeEffect(e.id, 'failed');
  assert.deepEqual(await h.order('o'), { status: 'declined', items: 2, charges: 1, refunds: 0 });
  assert.deepEqual(await h.pendingEffects(), []);
  for (const c of ['create', 'addItem', 'removeItem', 'place', 'ship', 'cancel']) refused(await h[c]('o'));
  assert.deepEqual(await h.retryPayment('o'), ok);
  refused(await h.retryPayment('o'));
  assert.deepEqual(await h.order('o'), { status: 'placed', items: 2, charges: 2, refunds: 0 });
  const [e2] = await h.pendingEffects();
  assert.notEqual(e2.id, e.id);
  assert.deepEqual({ from: e2.from, kind: e2.kind, data: e2.data }, { from: 'o', kind: 'payment.charge', data: { amount: 2 } });
  await h.completeEffect(e2.id, 'failed');
  assert.deepEqual(await h.order('o'), { status: 'failed', items: 2, charges: 2, refunds: 0 });
  assert.deepEqual(await h.pendingEffects(), []);
  for (const c of ['addItem', 'removeItem', 'place', 'ship', 'cancel', 'retryPayment']) refused(await h[c]('o'));
});

test('retry succeeds -> paid, ship; or cancel with refund', async () => {
  const h = await createHost();
  for (const id of ['s', 'c']) {
    await h.completeEffect((await placed(h, id, 1)).id, 'failed');
    await h.retryPayment(id);
    await h.completeEffect((await h.pendingEffects()).find((x) => x.from === id).id, 'ok');
    assert.equal((await h.order(id)).status, 'paid');
  }
  assert.deepEqual(await h.ship('s'), ok);
  assert.deepEqual(await h.order('s'), { status: 'shipped', items: 1, charges: 2, refunds: 0 });
  assert.deepEqual(await h.cancel('c'), ok);
  assert.deepEqual(await h.order('c'), { status: 'cancelled', items: 1, charges: 2, refunds: 1 });
});

test('cancel draft and paid', async () => {
  const h = await createHost();
  await h.create('d');
  assert.deepEqual(await h.cancel('d'), ok);
  assert.deepEqual(await h.order('d'), { status: 'cancelled', items: 0, charges: 0, refunds: 0 });
  refused(await h.cancel('d'));
  const e = await placed(h, 'p', 1);
  await h.completeEffect(e.id, 'ok');
  assert.deepEqual(await h.cancel('p'), ok);
  assert.deepEqual(await h.order('p'), { status: 'cancelled', items: 1, charges: 1, refunds: 1 });
  assert.deepEqual(await h.pendingEffects(), []);
  refused(await h.ship('p'));
  refused(await h.cancel('p'));
});

test('orders are independent; fresh hosts are independent', async () => {
  const h = await createHost();
  const a = await placed(h, 'a', 1);
  const b = await placed(h, 'b', 3);
  assert.notEqual(a.id, b.id);
  assert.equal((await h.pendingEffects()).length, 2);
  await h.completeEffect(b.id, 'ok');
  assert.equal((await h.order('a')).status, 'placed');
  assert.equal((await h.order('b')).status, 'paid');
  const h2 = await createHost();
  assert.equal(await h2.order('a'), null);
});

