const intent = () => ({ action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] });

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      status: { type: 'string' },
      items: { type: 'number' },
      charges: { type: 'number' },
      refunds: { type: 'number' },
      pending: { type: 'number' },
    },
    actions: {
      create: intent(),
      addItem: intent(),
      removeItem: intent(),
      place: intent(),
      ship: intent(),
      cancel: intent(),
      retryPayment: intent(),
