import { makeHost } from '../src/host.impl.ts';

const OUT = join(dirname(fileURLToPath(import.meta.url)), 'traces');
const windows = new Map(); // order -> windows
const h = makeHost(({ order, pre, action, post }) => {
  if (!windows.has(order)) windows.set(order, []);
  windows.get(order).push({ pre: { ...pre }, action, data: {}, post: { ...post } });
});

const charge = async (id) => (await h.pendingEffects()).find((e) => e.from === id);
const all = ['create', 'addItem', 'removeItem', 'place', 'ship', 'cancel', 'retryPayment'];
const poke = async (id) => { for (const c of all) await h[c](id); };
// While placed, cancel takes effect (cancelling); poke everything else.
const pokePlaced = async (id) => { for (const c of all) if (c !== 'cancel') await h[c](id); };

// happy path: fill to the cap, place, paid, ship, then glitches into shipped
{
  const id = 'happy';
  await h.ship(id); await h.addItem(id); // unknown order
  await h.create(id); await h.create(id);
  await h.removeItem(id); await h.place(id); await h.ship(id);
  for (let i = 0; i < 4; i++) await h.addItem(id);
  await h.removeItem(id); await h.addItem(id);
  await h.place(id);
  await pokePlaced(id);
  const e = await charge(id);
  await h.completeEffect(e.id, 'ok');
  await h.completeEffect(e.id, 'ok'); // already completed: no step
  await h.place(id); await h.addItem(id);
  await h.ship(id);
  await poke(id);
}
// paid then cancelled (refund)
{
  const id = 'refund';
  await h.create(id); await h.addItem(id); await h.place(id);
  await h.completeEffect((await charge(id)).id, 'ok');
  await h.cancel(id);
  await poke(id);
}
// first charge declined, retry declined too: failed
{
  const id = 'failed';
  await h.create(id); await h.addItem(id); await h.addItem(id); await h.place(id);
  await h.retryPayment(id);
  await h.completeEffect((await charge(id)).id, 'failed');
  await poke(id); // every command but retryPayment refused while declined; retry goes through
  await pokePlaced(id); // placed again: all refused
  await h.completeEffect((await charge(id)).id, 'failed');
  await poke(id);
}
// declined, retried, paid: one shipped, one cancelled with refund
for (const [id, end] of [['retryship', 'ship'], ['retrycancel', 'cancel']]) {
  await h.create(id); await h.addItem(id); await h.place(id);
  await h.completeEffect((await charge(id)).id, 'failed');
  await h.cancel(id); await h.ship(id); await h.addItem(id);
  await h.retryPayment(id);
  await h.completeEffect((await charge(id)).id, 'ok');
  await h.retryPayment(id);
  await h[end](id);
  await poke(id);
}
// cancelled while the charge is in progress: the answer decides the refund
for (const [id, answer, retry] of [['cancelok', 'ok', false], ['cancelfail', 'failed', false], ['cancelretry', 'failed', true], ['cancelretryok', 'ok', true]]) {
  await h.create(id); await h.addItem(id); await h.addItem(id); await h.place(id);
  if (retry) {
    await h.completeEffect((await charge(id)).id, 'failed');
    await h.retryPayment(id);
  }
  await h.cancel(id);
  await poke(id); // cancelling: every command refused
  await h.completeEffect((await charge(id)).id, answer);
  await poke(id);
}
// draft cancelled, empty and with items
{
  const id = 'draftcancel';
  await h.create(id); await h.cancel(id); await poke(id);
  const id2 = 'draftcancel2';
  await h.create(id2); await h.addItem(id2); await h.addItem(id2); await h.cancel(id2); await poke(id2);
}

rmSync(OUT, { recursive: true, force: true });
mkdirSync(OUT, { recursive: true });
